import { chromium } from 'playwright';
import fs from 'node:fs';
import assert from 'node:assert/strict';
const URL='https://basspauloandres-svg.github.io/hooklab-time/producer-interface-v0.5/';
const wav='/tmp/hooklab-e2e-120.wav';
function makeWav(path){const sr=22050,seconds=4,n=sr*seconds,b=Buffer.alloc(44+n*2);b.write('RIFF',0);b.writeUInt32LE(36+n*2,4);b.write('WAVE',8);b.write('fmt ',12);b.writeUInt32LE(16,16);b.writeUInt16LE(1,20);b.writeUInt16LE(1,22);b.writeUInt32LE(sr,24);b.writeUInt32LE(sr*2,28);b.writeUInt16LE(2,32);b.writeUInt16LE(16,34);b.write('data',36);b.writeUInt32LE(n*2,40);for(let i=0;i<n;i++){const p=i%(sr/2),v=p<500?Math.round(16000*Math.sin(2*Math.PI*1000*p/sr)*Math.exp(-p/100)):0;b.writeInt16LE(v,44+i*2)}fs.writeFileSync(path,b)}makeWav(wav);
const browser=await chromium.launch({headless:true,args:['--autoplay-policy=no-user-gesture-required']});const page=await browser.newPage({acceptDownloads:true});page.setDefaultTimeout(180000);await page.goto(URL,{waitUntil:'domcontentloaded',timeout:30000});assert.match(await page.title(),/Producer Interface v0\.5/);
await page.locator('#text').fill('Hook de control trazable');await page.locator('#intent').fill('directo');
await page.locator('#ref').setInputFiles({name:'e2e120.wav',mimeType:'audio/wav',buffer:fs.readFileSync(wav)});await page.waitForFunction(()=>document.querySelector('#refState')?.textContent?.includes('AUDIT_LOCAL_REFERENCE'));const pre=await page.evaluate(()=>state.aesthetic_reference);assert.equal(pre.scientific_ingestion,false);assert.equal(pre.gate_a_ingestion,false);assert.equal(pre.sha256.length,64);
await page.locator('#analyzeRef').click();await page.waitForFunction(()=>/ANALYSIS (PASS|FAIL)/.test(document.querySelector('#analysisState')?.textContent||''),null,{timeout:150000});assert.match(await page.locator('#analysisState').innerText(),/ANALYSIS PASS/);const a=await page.evaluate(()=>state.aesthetic_reference_analysis);assert.equal(a.analysis_mode,'LOCAL_ON_DEVICE_ONNX');assert.equal(a.source_audio_persistence,'NONE');assert.equal(a.m300_ingestion,false);assert.equal(a.success_evidence_ingestion,false);assert(a.tempo_bpm_median>100&&a.tempo_bpm_median<140);assert(a.beat_count>3);const ap=await page.locator('#analysisPanel').innerText();assert.match(ap,/Beat This small ONNX/);assert.match(ap,/Audio persistido\s*NONE/);
await page.locator('#midiBtn').click();assert.match(await page.locator('#buildState').innerText(),/D0 LISTO/);for(const v of ['thetic','anacrustic','syncopated']){await page.locator('#variant').selectOption(v);assert.equal(await page.locator('#downloadMidi').isEnabled(),true)}
await page.locator('#variant').selectOption('syncopated');const midiP=page.waitForEvent('download');await page.locator('#downloadMidi').click();const midi=await midiP;assert.equal(fs.readFileSync(await midi.path()).subarray(0,4).toString(),'MThd');const manP=page.waitForEvent('download');await page.locator('#downloadManifest').click();const man=JSON.parse(fs.readFileSync(await (await manP).path(),'utf8'));assert.equal(man.stimulus_class,'D0_EXPLORATORY');assert.equal(man.scientific_d,'BLOCKED');assert.equal(man.variants.length,3);
await page.locator('#start').click();await page.waitForTimeout(1200);assert.notEqual(await page.locator('#time').innerText(),'00:00');await page.locator('#stop').click();await page.locator('#decision').selectOption({label:'Modificar'});await page.locator('#reason').fill('Control E2E');await page.locator('#save').click();const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('hooklab_session_'+state.session_id)));assert.equal(saved.aesthetic_reference_analysis.role,'AESTHETIC_REFERENCE_ANALYSIS');assert.equal(saved.producer_evaluation.decision,'Modificar');assert.equal(saved.scientific_state.scientific_d,'BLOCKED');assert.equal(saved.d0_contract,'D0_EXPLORATORY != SCIENTIFIC_D');
const jsonP=page.waitForEvent('download');await page.locator('#export').click();const session=JSON.parse(fs.readFileSync(await (await jsonP).path(),'utf8'));assert.equal(session.version,'producer-interface-v0.5');assert.equal(session.aesthetic_reference_analysis.tempo_bpm_median,a.tempo_bpm_median);await browser.close();console.log(JSON.stringify({status:'PASS',version:session.version,bpm:a.tempo_bpm_median,beats:a.beat_count,d0_variants:man.variants.length,scientific_d:session.scientific_state.scientific_d},null,2));